#define AES_USE_HARDWARE_KEY    (BIT(4))
#define AES_USE_HARDWARE_KEY_M  (AES_USE_HARDWARE_KEY_V << AES_USE_HARDWARE_KEY_S)
#define AES_USE_HARDWARE_KEY_V  0x00000001U
#define AES_USE_HARDWARE_KEY_S  4

