        uint32_t mode:3;
        uint32_t reserved_3:1;
        /** use_hardware_key : R/W; bitpos: [4]; default: 0;
         *  Configures the AES accelerator use software key or hardware key.
         *  0: Software key.
         *  1: Hardware key.
         */
        uint32_t use_hardware_key:1;
