/** Group: Control and configuration registers */
/** Type of l1_icache_ctrl register
 *  L1 instruction Cache(L1-ICache) control register
 */
typedef union {
    struct {
        /** l1_icache_shut_ibus0 : R/W; bitpos: [0]; default: 0;
         *  Configures whether to disable IBUS0 to access icache.
         *  1: Disable
         */
        uint32_t l1_icache_shut_ibus0:1;
        /** l1_icache_shut_ibus1 : R/W; bitpos: [1]; default: 0;
         *  Configures whether to disable IBUS1 to access icache.
         *  1: Disable
         */
        uint32_t l1_icache_shut_ibus1:1;
        /** l1_icache_shut_ibus2 : R/W; bitpos: [2]; default: 0;
         *  Configures whether to disable IBUS2 to access ROM cache.
         *  1: Disable
         */
        uint32_t l1_icache_shut_ibus2:1;
        /** l1_icache_shut_ibus3 : R/W; bitpos: [3]; default: 0;
         *  Configures whether to disable IBUS3 to access ROM cache.
         *  1: Disable
         */
        uint32_t l1_icache_shut_ibus3:1;
        uint32_t reserved_4:4;
        /** l1_icache_undef_op : R/W; bitpos: [15:8]; default: 0;
         *  Internal debug control field.
         *  bits[1:0]: Arbitration mode.
         *    0: Round-robin, hold bus until data fetch completes.
         *    1: Round-robin, release bus after request is issued.
         *    2/3: Random arbitration.
         *  bit[5]: 1: Disable auto clock gating.
         */
        uint32_t l1_icache_undef_op:8;
        uint32_t reserved_16:16;
    };
    uint32_t val;
} cache_l1_icache_ctrl_reg_t;

