            uint32_t reserved2 : 4;                 /* Reserved */
            uint32_t aux_tx_snap_trig_miss : 1;     /* Auxiliary Timestamp Snapshot Trigger Missed */
            uint32_t aux_ts_snap_num : 5;           /* Number of Auxiliary Timestamp Snapshots */
            uint32_t reserved : 2;                  /* Reserved */
