#define GMAC_TXFSTS    (BIT(24))
#define GMAC_TXFSTS_M  (GMAC_TXFSTS_V << GMAC_TXFSTS_S)
#define GMAC_TXFSTS_V  0x00000001U
#define GMAC_TXFSTS_S  24
