#define GMAC_PCSLCHGIM    (BIT(1))
#define GMAC_PCSLCHGIM_M  (GMAC_PCSLCHGIM_V << GMAC_PCSLCHGIM_S)
#define GMAC_PCSLCHGIM_V  0x00000001U
