#define GMAC_PCSANCIM    (BIT(2))
#define GMAC_PCSANCIM_M  (GMAC_PCSANCIM_V << GMAC_PCSANCIM_S)
#define GMAC_PCSANCIM_V  0x00000001U
#define GMAC_PCSANCIM_S  2
