/** INTERRUPT_CORE1_SYS_ICM_INTR_MAP_REG register
 *  SYS_ICM_INTR mapping register
 */
#define INTERRUPT_CORE1_SYS_ICM_INTR_MAP_REG (DR_REG_INTERRUPT_CORE1_BASE + 0x0)
/** INTERRUPT_CORE1_SYS_ICM_INTR_MAP : R/W; bitpos: [5:0]; default: 0;
 *  Configures the interrupt source into one CPU interrupt.
 */
#define INTERRUPT_CORE1_SYS_ICM_INTR_MAP    0x0000003FU
#define INTERRUPT_CORE1_SYS_ICM_INTR_MAP_M  (INTERRUPT_CORE1_SYS_ICM_INTR_MAP_V << INTERRUPT_CORE1_SYS_ICM_INTR_MAP_S)
#define INTERRUPT_CORE1_SYS_ICM_INTR_MAP_V  0x0000003FU
#define INTERRUPT_CORE1_SYS_ICM_INTR_MAP_S  0
/** INTERRUPT_CORE1_SYS_ICM_INTR_PASS_LEVEL : R/W; bitpos: [9:8]; default: 0;
 *  Set as Non-zero value to enable interrupt-remap feature of the interrupt source.
 *  0=disable remap feature. 1=enable remap feature with S-Level. 2/3=enable remap
 *  feature with M-Level.
 */
#define INTERRUPT_CORE1_SYS_ICM_INTR_PASS_LEVEL    0x00000003U
#define INTERRUPT_CORE1_SYS_ICM_INTR_PASS_LEVEL_M  (INTERRUPT_CORE1_SYS_ICM_INTR_PASS_LEVEL_V << INTERRUPT_CORE1_SYS_ICM_INTR_PASS_LEVEL_S)
#define INTERRUPT_CORE1_SYS_ICM_INTR_PASS_LEVEL_V  0x00000003U
#define INTERRUPT_CORE1_SYS_ICM_INTR_PASS_LEVEL_S  8

