#define PMU_EXT_LDO_EN_VDET_M  (PMU_EXT_LDO_EN_VDET_V << PMU_EXT_LDO_EN_VDET_S)
#define PMU_EXT_LDO_EN_VDET_V  0x00000001U
#define PMU_EXT_LDO_EN_VDET_S  1
/** PMU_EXT_CUR_LIM : R/W; bitpos: [2]; default: 0;
 *  need_des
 */
#define PMU_EXT_CUR_LIM    (BIT(2))
#define PMU_EXT_CUR_LIM_M  (PMU_EXT_CUR_LIM_V << PMU_EXT_CUR_LIM_S)
#define PMU_EXT_CUR_LIM_V  0x00000001U
#define PMU_EXT_CUR_LIM_S  2
/** PMU_EXT_LDO_MUL : R/W; bitpos: [5:3]; default: 0;
 *  need_des
 */
#define PMU_EXT_LDO_MUL    0x00000007U
#define PMU_EXT_LDO_MUL_M  (PMU_EXT_LDO_MUL_V << PMU_EXT_LDO_MUL_S)
#define PMU_EXT_LDO_MUL_V  0x00000007U
#define PMU_EXT_LDO_MUL_S  3
/** PMU_EXT_LDO_DREF : R/W; bitpos: [9:6]; default: 0;
 *  need_des
 */
#define PMU_EXT_LDO_DREF    0x0000000FU
#define PMU_EXT_LDO_DREF_M  (PMU_EXT_LDO_DREF_V << PMU_EXT_LDO_DREF_S)
#define PMU_EXT_LDO_DREF_V  0x0000000FU
#define PMU_EXT_LDO_DREF_S  6

/** PMU_DEBUG_RO_REG register
 *  used for future potential eco, others don't care
 */
#define PMU_DEBUG_RO_REG (DR_REG_PMU_BASE + 0x21c)
/** PMU_CPU_PWR_STATE : RO; bitpos: [5:0]; default: 0;
 *  need_des
 */
#define PMU_CPU_PWR_STATE    0x0000003FU
#define PMU_CPU_PWR_STATE_M  (PMU_CPU_PWR_STATE_V << PMU_CPU_PWR_STATE_S)
#define PMU_CPU_PWR_STATE_V  0x0000003FU
#define PMU_CPU_PWR_STATE_S  0
/** PMU_IO_0P2A_OVDET : RO; bitpos: [6]; default: 0;
 *  need_des
 */
#define PMU_IO_0P2A_OVDET    (BIT(6))
#define PMU_IO_0P2A_OVDET_M  (PMU_IO_0P2A_OVDET_V << PMU_IO_0P2A_OVDET_S)
#define PMU_IO_0P2A_OVDET_V  0x00000001U
#define PMU_IO_0P2A_OVDET_S  6

/** PMU_LPCPU_WAKEUP_CAUSE_REG register
 *  need_des
 */
#define PMU_LPCPU_WAKEUP_CAUSE_REG (DR_REG_PMU_BASE + 0x220)
/** PMU_LPCPU_WAKEUP_CAUSE : RO; bitpos: [31:0]; default: 0;
 *  need_des
 */
#define PMU_LPCPU_WAKEUP_CAUSE    0xFFFFFFFFU
#define PMU_LPCPU_WAKEUP_CAUSE_M  (PMU_LPCPU_WAKEUP_CAUSE_V << PMU_LPCPU_WAKEUP_CAUSE_S)
#define PMU_LPCPU_WAKEUP_CAUSE_V  0xFFFFFFFFU
#define PMU_LPCPU_WAKEUP_CAUSE_S  0

/** PMU_BACKUP_WAIT_TARGET_REG register
 *  need_des
 */
#define PMU_BACKUP_WAIT_TARGET_REG (DR_REG_PMU_BASE + 0x224)
/** PMU_BACKUP_WAIT_TARGET : R/W; bitpos: [3:0]; default: 15;
 *  need_des
 */
#define PMU_BACKUP_WAIT_TARGET    0x0000000FU
#define PMU_BACKUP_WAIT_TARGET_M  (PMU_BACKUP_WAIT_TARGET_V << PMU_BACKUP_WAIT_TARGET_S)
#define PMU_BACKUP_WAIT_TARGET_V  0x0000000FU
#define PMU_BACKUP_WAIT_TARGET_S  0

/** PMU_DATE_REG register
 *  need_des
 */
#define PMU_DATE_REG (DR_REG_PMU_BASE + 0x3fc)
/** PMU_PMU_DATE : R/W; bitpos: [30:0]; default: 2427138;
 *  need_des
 */
#define PMU_PMU_DATE    0x7FFFFFFFU
#define PMU_PMU_DATE_M  (PMU_PMU_DATE_V << PMU_PMU_DATE_S)
#define PMU_PMU_DATE_V  0x7FFFFFFFU
#define PMU_PMU_DATE_S  0
/** PMU_CLK_EN : R/W; bitpos: [31]; default: 0;
 *  need_des
 */
#define PMU_CLK_EN    (BIT(31))
#define PMU_CLK_EN_M  (PMU_CLK_EN_V << PMU_CLK_EN_S)
#define PMU_CLK_EN_V  0x00000001U
#define PMU_CLK_EN_S  31

