#define SDHOST_CARDCLRINTEN_REG    (BIT(1))
#define SDHOST_CARDCLRINTEN_REG_M  (SDHOST_CARDCLRINTEN_REG_V << SDHOST_CARDCLRINTEN_REG_S)
#define SDHOST_CARDCLRINTEN_REG_V  0x00000001U
