#define SPI1_MEM_S_FDUMMY_WOUT_M  (SPI1_MEM_S_FDUMMY_WOUT_V << SPI1_MEM_S_FDUMMY_WOUT_S)
#define SPI1_MEM_S_FDUMMY_WOUT_V  0x00000001U
#define SPI1_MEM_S_FDUMMY_WOUT_S  3
