#define SPI1_MEM_S_FLASH_PES_COMMAND    0x0000FFFFU
#define SPI1_MEM_S_FLASH_PES_COMMAND_M  (SPI1_MEM_S_FLASH_PES_COMMAND_V << SPI1_MEM_S_FLASH_PES_COMMAND_S)
