/** SPI_SMEM_S_AC_REG register
 *  MSPI external RAM ECC and SPI CS timing control register
 */
#define SPI_SMEM_S_AC_REG (DR_REG_PSRAM_MSPI0_BASE + 0x1a0)
/** SPI_SMEM_S_CS_SETUP : R/W; bitpos: [0]; default: 0;
 *  For SPI0 and SPI1, spi cs is enable when spi is in prepare phase. 1: enable 0:
 *  disable.
 */
#define SPI_SMEM_S_CS_SETUP    (BIT(0))
#define SPI_SMEM_S_CS_SETUP_M  (SPI_SMEM_S_CS_SETUP_V << SPI_SMEM_S_CS_SETUP_S)
#define SPI_SMEM_S_CS_SETUP_V  0x00000001U
#define SPI_SMEM_S_CS_SETUP_S  0
/** SPI_SMEM_S_CS_HOLD : R/W; bitpos: [1]; default: 0;
 *  For SPI0 and SPI1, spi cs keep low when spi is in done phase. 1: enable 0: disable.
 */
