#define SPI_SMEM_S_CS_HOLD_M  (SPI_SMEM_S_CS_HOLD_V << SPI_SMEM_S_CS_HOLD_S)
#define SPI_SMEM_S_CS_HOLD_V  0x00000001U
#define SPI_SMEM_S_CS_HOLD_S  1
/** SPI_SMEM_S_CS_SETUP_TIME : R/W; bitpos: [6:2]; default: 1;
 *  For spi0, (cycles-1) of prepare phase by spi clock this bits are combined with
 *  spi_mem_cs_setup bit.
 */
#define SPI_SMEM_S_CS_SETUP_TIME    0x0000001FU
#define SPI_SMEM_S_CS_SETUP_TIME_M  (SPI_SMEM_S_CS_SETUP_TIME_V << SPI_SMEM_S_CS_SETUP_TIME_S)
#define SPI_SMEM_S_CS_SETUP_TIME_V  0x0000001FU
#define SPI_SMEM_S_CS_SETUP_TIME_S  2
/** SPI_SMEM_S_CS_HOLD_TIME : R/W; bitpos: [11:7]; default: 1;
 *  For SPI0 and SPI1, spi cs signal is delayed to inactive by spi clock this bits are
 *  combined with spi_mem_cs_hold bit.
 */
