#define SPI_SMEM_S_CS_HOLD_TIME_M  (SPI_SMEM_S_CS_HOLD_TIME_V << SPI_SMEM_S_CS_HOLD_TIME_S)
#define SPI_SMEM_S_CS_HOLD_TIME_V  0x0000001FU
#define SPI_SMEM_S_CS_HOLD_TIME_S  7
/** SPI_SMEM_S_ECC_CS_HOLD_TIME : R/W; bitpos: [14:12]; default: 3;
 *  SPI_SMEM_S_CS_HOLD_TIME + SPI_SMEM_S_ECC_CS_HOLD_TIME is the SPI0 and SPI1 CS hold
 *  cycles in ECC mode when accessed external RAM.
 */
#define SPI_SMEM_S_ECC_CS_HOLD_TIME    0x00000007U
#define SPI_SMEM_S_ECC_CS_HOLD_TIME_M  (SPI_SMEM_S_ECC_CS_HOLD_TIME_V << SPI_SMEM_S_ECC_CS_HOLD_TIME_S)
