#define SPI_SMEM_S_ECC_CS_HOLD_TIME_S  12
/** SPI_SMEM_S_ECC_SKIP_PAGE_CORNER : R/W; bitpos: [15]; default: 1;
 *  1: SPI0 skips page corner when accesses external RAM. 0: Not skip page corner when
 *  accesses external RAM.
 */
#define SPI_SMEM_S_ECC_SKIP_PAGE_CORNER    (BIT(15))
#define SPI_SMEM_S_ECC_SKIP_PAGE_CORNER_M  (SPI_SMEM_S_ECC_SKIP_PAGE_CORNER_V << SPI_SMEM_S_ECC_SKIP_PAGE_CORNER_S)
