#define SPI_MEM_S_PSEUDO_RNG_CNT    0x00000007U
#define SPI_MEM_S_PSEUDO_RNG_CNT_M  (SPI_MEM_S_PSEUDO_RNG_CNT_V << SPI_MEM_S_PSEUDO_RNG_CNT_S)
